values ('item-tamburins-seongsu', (select id from public.couple_venues where source_key = 'venue-tamburins-seongsu'), 'permanent', '탬버린즈 플래그십스토어 성수점', '향 제품을 시향하고 설치형 공간을 함께 둘러보며 서로의 취향을 이야기하기 좋은 뷰티 플래그십입니다.', 'culture', array['experience', 'walk_culture']::text[], 'experience', array['walk_culture']::text[], 'low', 'balanced', 'evergreen', '공식 고객서비스에서 성수 플래그십 운영을 확인했고 시즌 디스플레이 변화는 분기별 검수합니다.', '2026-09-01T12:00:00+09:00'::timestamptz, '2026-11-30T12:00:00+09:00'::timestamptz, null::timestamptz, 'under_40000', 25000, 0, 'optional_purchase', '공간 체험 무료, 향 제품 구매는 선택', 75, 'indoor', 'low', 'medium', false, 5, 'active', null::timestamptz, null::timestamptz, '2026-09-01T12:00:00+09:00'::timestamptz, '[{"kind":"official","url":"https://www.tamburins.com/kr/mypage/cs/customer-service/","checked_at":"2026-09-01"}]'::jsonb, 5, 4, 5, 4, 4, 2, 85, 'hero', '향과 공간 연출을 함께 경험해 단순 구매보다 대화와 취향 탐색이 생기는 목적형 매장입니다.', '2026-09-01T12:00:00+09:00'::timestamptz, '2026-12-01T12:00:00+09:00'::timestamptz, '[{"kind":"official","url":"https://www.tamburins.com/kr/mypage/cs/customer-service/","checked_at":"2026-09-01"}]'::jsonb, 'couple-editorial-v1', 'independent_couple_research', false, null, null::timestamptz, null::timestamptz, 'walk_in_only', '2026-09-01T12:00:00+09:00'::timestamptz, '2026-10-01T12:00:00+09:00'::timestamptz, 'alternative_only', '2026-09-01T15:00:00+09:00'::timestamptz, 'couple-human-curation-v1', 'production', 'couple-production-phase1b2b-v1', now())
