values ('item-groot-climbing', (select id from public.couple_venues where source_key = 'venue-groot-climbing'), 'permanent', '그루트클라이밍', '초보도 장비를 빌려 함께 도전하고 서로 응원하는 경험이 분명한 성수 실내 볼더링장입니다.', 'experience', array['experience']::text[], 'experience', array[]::text[], 'high', 'balanced', 'evergreen', '2026년 9월 현장 모임과 8월 운영 정보가 확인됐으며 폐업한 인근 클라이밍파크와 구분해 검수했습니다.', '2026-09-01T12:00:00+09:00'::timestamptz, '2026-10-31T12:00:00+09:00'::timestamptz, null::timestamptz, 'under_40000', 23000, 20000, 'admission', '일일 이용권 20,000원과 암벽화 대여 예상', 150, 'indoor', 'high', 'low', false, 4, 'active', null::timestamptz, null::timestamptz, '2026-09-01T12:00:00+09:00'::timestamptz, '[{"kind":"verification","url":"https://crux-climb.com/gyms/18f26b1f-c2cd-4873-9124-8db0962da637","checked_at":"2026-09-01"}]'::jsonb, 5, 4, 4, 4, 5, 3, 79, 'standard', '성인이 함께 도전하고 응원할 수 있는 활동형 데이트로 성수의 부족한 high energy 선택지를 채웁니다.', '2026-09-01T12:00:00+09:00'::timestamptz, '2026-11-01T12:00:00+09:00'::timestamptz, '[{"kind":"verification","url":"https://crux-climb.com/gyms/18f26b1f-c2cd-4873-9124-8db0962da637","checked_at":"2026-09-01"}]'::jsonb, 'couple-editorial-v1', 'independent_couple_research', false, null, null::timestamptz, null::timestamptz, 'walk_in_only', '2026-09-01T12:00:00+09:00'::timestamptz, '2026-10-01T12:00:00+09:00'::timestamptz, 'keep_primary', '2026-09-01T15:00:00+09:00'::timestamptz, 'couple-human-curation-v1', 'production', 'couple-production-phase1b2b-v1', now())
