values ('item-oliveyoung-n-seongsu', (select id from public.couple_venues where source_key = 'venue-oliveyoung-n-seongsu'), 'permanent', '올리브영 N성수', '팝업 쇼룸과 뷰티 서비스, 라운지가 층별로 이어져 최신 K-뷰티를 함께 탐색하는 혁신 매장입니다.', 'culture', array['experience', 'walk_culture']::text[], 'experience', array['walk_culture']::text[], 'medium', 'balanced', 'evergreen', 'CJ 공식 자료에서 체험·팝업 중심의 5층 혁신 매장 운영을 확인했고 콘텐츠를 월별 재검수합니다.', '2026-09-01T12:00:00+09:00'::timestamptz, '2026-10-31T12:00:00+09:00'::timestamptz, null::timestamptz, 'under_20000', 15000, 0, 'optional_purchase', '입장과 기본 체험 무료, 제품·라운지 구매는 선택', 120, 'indoor', 'medium', 'high', false, 5, 'active', null::timestamptz, null::timestamptz, '2026-09-01T12:00:00+09:00'::timestamptz, '[{"kind":"official","url":"https://cjnews.cj.net/?p=56585","checked_at":"2026-09-01"}]'::jsonb, 5, 4, 5, 4, 4, 2, 85, 'hero', '뷰티 체험과 취향 탐색을 결합한 최신 대형 플래그십으로 단순 쇼핑보다 함께 즐길 요소가 분명합니다.', '2026-09-01T12:00:00+09:00'::timestamptz, '2026-11-01T12:00:00+09:00'::timestamptz, '[{"kind":"official","url":"https://cjnews.cj.net/?p=56585","checked_at":"2026-09-01"}]'::jsonb, 'couple-editorial-v1', 'independent_couple_research', false, null, null::timestamptz, null::timestamptz, 'walk_in_only', '2026-09-01T12:00:00+09:00'::timestamptz, '2026-10-01T12:00:00+09:00'::timestamptz, 'alternative_only', '2026-09-01T15:00:00+09:00'::timestamptz, 'couple-human-curation-v1', 'production', 'couple-production-phase1b2b-v1', now())
