values ('item-code-k-hongdae', (select id from public.couple_venues where source_key = 'venue-code-k-hongdae'), 'permanent', '코드케이 홍대점', '큰 단일 테마 공간에서 75분 동안 함께 움직이고 문제를 푸는 프리미엄 방탈출 체험입니다.', 'entertainment', array['experience']::text[], 'experience', array[]::text[], 'high', 'balanced', 'evergreen', '2026년 6월 갱신된 장소 정보와 Kakao에서 현재 운영·주소를 교차 확인했습니다.', '2026-09-01T12:00:00+09:00'::timestamptz, '2026-10-31T12:00:00+09:00'::timestamptz, null::timestamptz, 'under_40000', 25000, 25000, 'program_fee', '75분 테마 1인 예상가, 예약 시 최종 확인', 120, 'indoor', 'medium', 'low', false, 4, 'active', null::timestamptz, null::timestamptz, '2026-09-01T12:00:00+09:00'::timestamptz, '[{"kind":"verification","url":"https://web.zamfit.kr/stores/1968/%EC%BD%94%EB%93%9C%EC%BC%80%EC%9D%B4-%ED%99%8D%EB%8C%80%EC%A0%90","checked_at":"2026-09-01"}]'::jsonb, 5, 4, 4, 4, 5, 3, 79, 'standard', '협력형 방탈출을 원하는 커플에게 명확한 목적과 공동 경험을 제공하는 홍대 활동 선택지입니다.', '2026-09-01T12:00:00+09:00'::timestamptz, '2026-12-01T12:00:00+09:00'::timestamptz, '[{"kind":"verification","url":"https://web.zamfit.kr/stores/1968/%EC%BD%94%EB%93%9C%EC%BC%80%EC%9D%B4-%ED%99%8D%EB%8C%80%EC%A0%90","checked_at":"2026-09-01"}]'::jsonb, 'couple-editorial-v1', 'independent_couple_research', true, 'https://www.code-k.co.kr/', null::timestamptz, null::timestamptz, 'available', '2026-09-01T12:00:00+09:00'::timestamptz, '2026-10-01T12:00:00+09:00'::timestamptz, 'keep_primary', '2026-09-01T15:00:00+09:00'::timestamptz, 'couple-human-curation-v1', 'production', 'couple-production-phase1b2b-v1', now())
