values ('item-zero-world-hongdae', (select id from public.couple_venues where source_key = 'venue-zero-world-hongdae'), 'permanent', '제로월드 홍대점', '스토리와 공간 연출이 강한 여러 테마에서 서로 역할을 나눠 해결하는 홍대 방탈출 공간입니다.', 'entertainment', array['experience']::text[], 'experience', array[]::text[], 'high', 'balanced', 'evergreen', '공식 홍대점 페이지에서 위치와 예약 동선을 확인했고 테마·가격을 월별 검수합니다.', '2026-09-01T12:00:00+09:00'::timestamptz, '2026-10-31T12:00:00+09:00'::timestamptz, null::timestamptz, 'under_40000', 28000, 28000, 'program_fee', '테마별 1인 예상가, 공식 예약에서 최종 확인', 120, 'indoor', 'medium', 'medium', false, 5, 'active', null::timestamptz, null::timestamptz, '2026-09-01T12:00:00+09:00'::timestamptz, '[{"kind":"official","url":"https://www.zerohongdae.com/map","checked_at":"2026-09-01"}]'::jsonb, 5, 5, 4, 5, 5, 2, 91, 'hero', '테마 완성도와 협력 경험이 선명한 방탈출로 특별하고 활동적인 데이트를 원하는 커플에게 적합합니다.', '2026-09-01T12:00:00+09:00'::timestamptz, '2026-12-01T12:00:00+09:00'::timestamptz, '[{"kind":"official","url":"https://www.zerohongdae.com/map","checked_at":"2026-09-01"}]'::jsonb, 'couple-editorial-v1', 'independent_couple_research', true, 'https://www.zerohongdae.com/', null::timestamptz, null::timestamptz, 'available', '2026-09-01T12:00:00+09:00'::timestamptz, '2026-10-01T12:00:00+09:00'::timestamptz, 'keep_primary', '2026-09-01T15:00:00+09:00'::timestamptz, 'couple-human-curation-v1', 'production', 'couple-production-phase1b2b-v1', now())
