values ('item-redbutton-layered-hongdae', (select id from public.couple_venues where source_key = 'venue-redbutton-layered-hongdae'), 'permanent', '레드버튼 레이어드 홍대점', '다양한 보드게임을 골라 경쟁하거나 협력하며 대화를 자연스럽게 이어가기 좋은 실내 놀이 공간입니다.', 'entertainment', array['experience', 'cafe']::text[], 'experience', array['cafe']::text[], 'medium', 'proven', 'evergreen', '브랜드 공식 채널과 Kakao에서 레이어드 홍대점 운영을 확인했고 요금은 분기별 검수합니다.', '2026-09-01T12:00:00+09:00'::timestamptz, '2026-11-30T12:00:00+09:00'::timestamptz, null::timestamptz, 'under_20000', 12000, 5000, 'program_fee', '시간 이용료와 음료를 포함한 일반 지출 예상', 150, 'indoor', 'low', 'medium', false, 5, 'active', null::timestamptz, null::timestamptz, '2026-09-01T12:00:00+09:00'::timestamptz, '[{"kind":"official","url":"https://redbutton.co.kr/","checked_at":"2026-09-01"}]'::jsonb, 4, 4, 4, 4, 4, 3, 70, 'standard', '게임을 고르고 함께 플레이하는 과정이 자연스럽게 대화와 상호작용을 만드는 실내 활동 데이트입니다.', '2026-09-01T12:00:00+09:00'::timestamptz, '2026-12-01T12:00:00+09:00'::timestamptz, '[{"kind":"official","url":"https://redbutton.co.kr/","checked_at":"2026-09-01"}]'::jsonb, 'couple-editorial-v1', 'independent_couple_research', false, null, null::timestamptz, null::timestamptz, 'walk_in_only', '2026-09-01T12:00:00+09:00'::timestamptz, '2026-10-01T12:00:00+09:00'::timestamptz, 'keep_primary', '2026-09-01T15:00:00+09:00'::timestamptz, 'couple-human-curation-v1', 'production', 'couple-production-phase1b2b-v1', now())
