values ('item-music-complex-seoul', (select id from public.couple_venues where source_key = 'venue-music-complex-seoul'), 'permanent', '뮤직컴플렉스서울', '각자 고른 LP를 헤드폰으로 함께 듣고 음악 이야기를 나누는 인사동의 목적형 음악 카페입니다.', 'cafe', array['cafe', 'experience']::text[], 'cafe', array['experience']::text[], 'low', 'balanced', 'evergreen', 'Kakao 장소와 공식 소셜 채널에서 운영을 확인했고 이용 정책과 메뉴를 월별 재검수합니다.', '2026-09-01T12:00:00+09:00'::timestamptz, '2026-10-31T12:00:00+09:00'::timestamptz, null::timestamptz, 'under_20000', 20000, 15000, 'minimum_purchase', '음료와 LP 좌석 이용을 포함한 일반 지출 예상', 150, 'indoor', 'low', 'medium', false, 5, 'active', null::timestamptz, null::timestamptz, '2026-09-01T12:00:00+09:00'::timestamptz, '[{"kind":"official","url":"https://www.instagram.com/music.complex.seoul/","checked_at":"2026-09-01"}]'::jsonb, 5, 4, 4, 4, 5, 3, 79, 'standard', 'LP를 함께 고르고 듣는 과정이 일반 카페와 다른 취향 대화를 만드는 종로의 목적형 음악 공간입니다.', '2026-09-01T12:00:00+09:00'::timestamptz, '2026-11-01T12:00:00+09:00'::timestamptz, '[{"kind":"official","url":"https://www.instagram.com/music.complex.seoul/","checked_at":"2026-09-01"}]'::jsonb, 'couple-editorial-v1', 'independent_couple_research', false, null, null::timestamptz, null::timestamptz, 'walk_in_only', '2026-09-01T12:00:00+09:00'::timestamptz, '2026-10-01T12:00:00+09:00'::timestamptz, 'alternative_only', '2026-09-01T15:00:00+09:00'::timestamptz, 'couple-human-curation-v1', 'production', 'couple-production-phase1b2b-v1', now())
