values ('item-fritz-wonso', (select id from public.couple_venues where source_key = 'venue-fritz-wonso'), 'permanent', '프릳츠 원서점', '고즈넉한 원서동 건물과 검증된 커피·빵을 함께 즐기며 오래 대화하기 좋은 카페입니다.', 'cafe', array['cafe', 'walk_culture']::text[], 'cafe', array['walk_culture']::text[], 'low', 'proven', 'evergreen', '프릳츠 공식 채널과 Kakao 장소에서 원서점 운영을 확인했고 가격·혼잡도를 분기별 검수합니다.', '2026-09-01T12:00:00+09:00'::timestamptz, '2026-11-30T12:00:00+09:00'::timestamptz, null::timestamptz, 'under_20000', 12000, 5000, 'minimum_purchase', '음료와 베이커리 일반 주문 기준', 120, 'mixed', 'low', 'medium', false, 4, 'active', null::timestamptz, null::timestamptz, '2026-09-01T12:00:00+09:00'::timestamptz, '[{"kind":"official","url":"https://fritz.co.kr/","checked_at":"2026-09-01"}]'::jsonb, 4, 4, 4, 4, 4, 3, 70, 'standard', '한옥과 커피의 목적성이 분명해 종로에서 편하게 쉬며 대화하려는 커플에게 검증된 선택지입니다.', '2026-09-01T12:00:00+09:00'::timestamptz, '2026-12-01T12:00:00+09:00'::timestamptz, '[{"kind":"official","url":"https://fritz.co.kr/","checked_at":"2026-09-01"}]'::jsonb, 'couple-editorial-v1', 'independent_couple_research', false, null, null::timestamptz, null::timestamptz, 'walk_in_only', '2026-09-01T12:00:00+09:00'::timestamptz, '2026-10-01T12:00:00+09:00'::timestamptz, 'alternative_only', '2026-09-01T15:00:00+09:00'::timestamptz, 'couple-human-curation-v1', 'production', 'couple-production-phase1b2b-v1', now())
