values ('item-theclimb-seongsu', (select id from public.couple_venues where source_key = 'venue-theclimb-seongsu'), 'permanent', '더클라임 성수점', '초보 강습과 난이도별 볼더링을 통해 둘이 서로 응원하며 몸을 쓰는 실내 클라이밍 공간입니다.', 'experience', array['experience']::text[], 'experience', array[]::text[], 'high', 'balanced', 'recent', '공식 지점 링크와 2026년 7월 갱신된 운영 정보에서 성수점 운영을 확인했습니다.', '2026-09-01T18:00:00+09:00'::timestamptz, '2026-10-01T00:00:00+09:00'::timestamptz, '2027-03-01T00:00:00+09:00'::timestamptz, 'under_40000', 25000, 22000, 'admission', '일일 이용권과 장비 대여를 포함한 일반 방문 예상액', 150, 'indoor', 'medium', 'low', false, 4, 'active', null::timestamptz, null::timestamptz, '2026-09-01T18:00:00+09:00'::timestamptz, '[{"kind":"official_or_trusted","url":"https://linktr.ee/theclimb_life","checked_at":"2026-09-01"}]'::jsonb, 5, 4, 4, 4, 4, 2, 81, 'standard', '게임이 아닌 성인 활동형 경험이며 둘이 함께 도전하고 응원하는 목적성이 선명합니다.', '2026-09-01T18:00:00+09:00'::timestamptz, '2026-10-01T00:00:00+09:00'::timestamptz, '[{"kind":"official_or_trusted","url":"https://linktr.ee/theclimb_life","checked_at":"2026-09-01"}]'::jsonb, 'couple-editorial-v1', 'independent_couple_research', false, null, null::timestamptz, null::timestamptz, 'walk_in_only', '2026-09-01T18:00:00+09:00'::timestamptz, '2026-10-01T00:00:00+09:00'::timestamptz, 'keep_primary', '2026-09-01T18:00:00+09:00'::timestamptz, 'couple-human-curation-v1', 'production', 'couple-production-phase1b2b-v1', now())
