values ('item-about-the-chapter', (select id from public.couple_venues where source_key = 'venue-about-the-chapter'), 'permanent', '어바웃더챕터', '책과 음악이 있는 조용한 공간에서 각자 고른 이야기를 함께 나누기 좋은 서울숲 북카페입니다.', 'cafe', array['cafe', 'walk_culture']::text[], 'cafe', array['walk_culture']::text[], 'low', 'balanced', 'recent', 'Kakao 현재 영업 정보와 공식 소셜 채널을 2026년 9월에 확인했습니다.', '2026-09-01T18:00:00+09:00'::timestamptz, '2026-10-01T00:00:00+09:00'::timestamptz, '2027-03-01T00:00:00+09:00'::timestamptz, 'under_20000', 12000, 6000, 'minimum_purchase', '음료와 디저트 선택 시 일반 예상액', 90, 'indoor', 'low', 'low', false, 4, 'active', null::timestamptz, null::timestamptz, '2026-09-01T18:00:00+09:00'::timestamptz, '[{"kind":"official_or_trusted","url":"https://www.instagram.com/about.the.chapter/","checked_at":"2026-09-01"}]'::jsonb, 5, 4, 4, 4, 4, 3, 76, 'standard', '짧고 조용한 실내 데이트 목적이 분명해 성수 카페·저에너지·1~2시간 공백을 직접 보완합니다.', '2026-09-01T18:00:00+09:00'::timestamptz, '2026-10-01T00:00:00+09:00'::timestamptz, '[{"kind":"official_or_trusted","url":"https://www.instagram.com/about.the.chapter/","checked_at":"2026-09-01"}]'::jsonb, 'couple-editorial-v1', 'independent_couple_research', false, null, null::timestamptz, null::timestamptz, 'walk_in_only', '2026-09-01T18:00:00+09:00'::timestamptz, '2026-10-01T00:00:00+09:00'::timestamptz, 'alternative_only', '2026-09-01T18:00:00+09:00'::timestamptz, 'couple-human-curation-v1', 'production', 'couple-production-phase1b2b-v1', now())
