select

  (select count(*) from public.couple_venues where status = 'active') as active_venues,

  (select count(*) from public.couple_recommendation_items where dataset_version = 'couple-production-phase1b2b-v1') as pilot_items,

  (select count(*) from public.couple_recommendation_catalog where dataset_version = 'couple-production-phase1b2b-v1' and recommendation_eligible) as eligible_items;

